INSERT INTO reviewed_plant_passports VALUES
 (32,'Ананас Корона','{"humidity":"Ананас переносит невысокую или умеренную влажность воздуха. Не ставьте горшок под горячую струю от батареи и обеспечьте движение воздуха без сквозняка.","temperature":"Теплолюбивый ананас содержите в помещении без холодных сквозняков, круглый год в светлом месте. Мороз для него губителен.","soil":"Нужен рыхлый, хорошо дренируемый субстрат для наземных бромелиевых. Дренажные отверстия обязательны, застой воды у корней недопустим.","repotting":"Пересаживайте весной, когда корни заполнят горшок, в чуть более просторную ёмкость. После плодоношения материнская розетка обычно даёт боковые отпрыски.","fertilizer":"Во время активного роста и плодоношения подкармливайте сбалансированным жидким удобрением по инструкции; при слабом росте зимой сократите подкормку.","growthRate":"Розетка постепенно наращивает листья; после цветения формируется плод, а затем материнское растение даёт отпрыски и со временем стареет."}'::jsonb),
 (41,'Аспидистра Elatior Milky Way','{"humidity":"Обычная влажность квартиры подходит; специально повышать её для аспидистры не требуется.","temperature":"Лучше содержать в прохладной комнате при 5–20 °C, подальше от горячей батареи.","soil":"Подойдёт рыхлый универсальный субстрат для комнатных растений в горшке с дренажными отверстиями.","repotting":"Пересаживайте весной только при тесном горшке; крупный куст можно разделить, сохранив на каждой части несколько листьев.","fertilizer":"С весны до конца лета можно подкармливать универсальным удобрением для комнатных растений раз в месяц.","growthRate":"Растёт неспешно, постепенно наращивая плотный куст из отдельных листьев; в слабом свете рост ещё медленнее."}'::jsonb),
 (42,'Аспидистра Элатиор','{"humidity":"Обычная влажность квартиры подходит; специально повышать её для аспидистры не требуется.","temperature":"Лучше содержать в прохладной комнате при 5–20 °C, подальше от горячей батареи.","soil":"Подойдёт рыхлый универсальный субстрат для комнатных растений в горшке с дренажными отверстиями.","repotting":"Пересаживайте весной только при тесном горшке; крупный куст можно разделить, сохранив на каждой части несколько листьев.","fertilizer":"С весны до конца лета можно подкармливать универсальным удобрением для комнатных растений раз в месяц.","growthRate":"Растёт неспешно, постепенно наращивая плотный куст из отдельных листьев; в слабом свете рост ещё медленнее."}'::jsonb),
 (46,'Бамбук Лаки Драцена Сандериана','{"humidity":"При обычной комнатной влажности драцена Сандера растёт нормально. Держите вдали от горячей батареи и не оставляйте корни в застоявшейся воде.","temperature":"Держите в тёплой комнате без холодных сквозняков и резких перепадов температуры.","soil":"Для выращивания в горшке подойдёт рыхлый дренируемый субстрат для комнатных растений. Если стебли стоят в воде, регулярно меняйте её и промывайте ёмкость.","repotting":"Растения в грунте пересаживайте весной, когда корни заполнят горшок. Стебли, выращиваемые в воде, переносят в грунт аккуратно, не заглубляя их чрезмерно.","fertilizer":"В грунте подкармливайте во время роста слабым раствором удобрения для комнатных растений по инструкции; при выращивании в воде используйте только подходящие малые дозы.","growthRate":"Удлинение стеблей и появление новых листьев обычно умеренное; при недостатке света рост замедляется."}'::jsonb),
 (47,'Бамбук Лаки Драцена Сандериана прямой','{"humidity":"При обычной комнатной влажности драцена Сандера растёт нормально. Держите вдали от горячей батареи и не оставляйте корни в застоявшейся воде.","temperature":"Держите в тёплой комнате без холодных сквозняков и резких перепадов температуры.","soil":"Для выращивания в горшке подойдёт рыхлый дренируемый субстрат для комнатных растений. Если стебли стоят в воде, регулярно меняйте её и промывайте ёмкость.","repotting":"Растения в грунте пересаживайте весной, когда корни заполнят горшок. Стебли, выращиваемые в воде, переносят в грунт аккуратно, не заглубляя их чрезмерно.","fertilizer":"В грунте подкармливайте во время роста слабым раствором удобрения для комнатных растений по инструкции; при выращивании в воде используйте только подходящие малые дозы.","growthRate":"Удлинение стеблей и появление новых листьев обычно умеренное; при недостатке света рост замедляется."}'::jsonb),
 (56,'Бонсай Гранат','{"humidity":"Гранат — уличный бонсай, поэтому повышать комнатную влажность ему не нужно. Маленькую плошку в жару проверяйте чаще, чтобы корневой ком не высыхал полностью.","temperature":"Это листопадное растение с зимним покоем. Держите на солнце в тёплый сезон, а зимой в светлом прохладном защищённом от сильного мороза месте.","soil":"Используйте рыхлый дренируемый субстрат для уличного бонсай. В плошке нужны отверстия для свободного стока воды.","repotting":"Пересаживайте ранней весной при тесном корневом коме, осторожно обновляя субстрат и подрезая корни по правилам бонсай.","fertilizer":"В сезон роста подкармливайте небольшими дозами сбалансированного удобрения для бонсай по инструкции. Во время зимнего покоя подкормка не нужна.","growthRate":"Весной выпускает листья, летом формирует побеги и цветки; осенью листья опадают. В плошке прирост ограничен формировкой."}'::jsonb),
 (64,'Бонсай Лжелиственница','{"temperature":"Это листопадное дерево открытого грунта, которому нужна естественная прохладная зимовка. Не держите бонсай круглый год в тёплой комнате; контейнерные корни зимой защищайте от сильного промерзания.","soil":"Подходит слабокислый или нейтральный, хорошо дренируемый субстрат, который сохраняет умеренную влажность и не содержит избытка извести.","repotting":"Бонсай пересаживают с осторожной работой с корнями весной, а в мягком климате также осенью; частоту определяют по заполнению плошки корнями.","fertilizer":"Подкормки у уличного бонсай проводят преимущественно в период роста с весны до осени; зимой в покое не подкармливают.","growthRate":"Лжелиственница растёт медленно как дерево; осенью хвоя желтеет и опадает, весной появляется новая. Зимой отсутствие хвои нормально."}'::jsonb),
 (65,'Бонсай Лигуструм (Бирючина китайская)','{"humidity":"Бирючине на открытом воздухе специальное увлажнение не требуется. В маленькой плошке проверяйте влажность субстрата чаще, особенно летом.","temperature":"Это уличный бонсай: бирючине нужен сезонный ход температуры. Зимой защищайте корни в неглубокой плошке от сильного промерзания.","soil":"Нужен рыхлый, хорошо дренируемый субстрат для уличного бонсай. Длительный застой воды у корней нежелателен.","repotting":"Проверяйте корни весной. Если они плотно оплели ком, обновите субстрат и осторожно подрежьте корни, сохраняя форму плошки.","fertilizer":"В период роста вносите сбалансированное удобрение для бонсай малыми дозами по инструкции; зимой не подкармливайте.","growthRate":"Бирючина образует новые побеги в тёплый сезон и хорошо реагирует на формирующую обрезку. Зимой рост замедляется."}'::jsonb),
 (70,'Бонсай Можжевельник','{"humidity":"Уличный можжевельник нуждается в свежем воздухе; сухой жаркий воздух квартиры не заменяет наружное содержание.","temperature":"Это уличный бонсай с сезонным циклом. Зимой не переносите в тёплую комнату; защищайте маленький контейнер от промерзания корней и иссушающего ветра.","soil":"Используйте рыхлый, хорошо дренируемый субстрат для уличных хвойных бонсай; застой воды у корней недопустим.","repotting":"Проверяйте корневой ком весной; пересадку и работу с корнями выполняйте весной или осенью в мягком климате, не по произвольному календарю.","fertilizer":"Подкармливайте умеренно с весны до осени удобрением для бонсай по инструкции; во время зимнего покоя не подкармливайте.","growthRate":"Растёт сезонно; новые хвойные побеги появляются главным образом весной и летом, зимой рост почти прекращается."}'::jsonb),
 (79,'Бонсай Сагереция чайная','{"humidity":"Сагереции полезен умеренно влажный воздух; держите её вдали от батареи. Поддон с влажным керамзитом ставьте так, чтобы плошка не стояла в воде.","temperature":"Этот теплолюбивый бонсай выращивайте в помещении, защищая от холодных сквозняков. В тёплый сезон можно постепенно приучать к защищённому месту на улице.","soil":"Используйте рыхлый, дренируемый субстрат для комнатных бонсай; небольшой объём плошки должен пропускать воду и воздух к корням.","repotting":"Весной проверяйте, не заполнили ли корни плошку. При необходимости осторожно обновите субстрат и слегка подрежьте корни.","fertilizer":"Весной и летом используйте сбалансированное удобрение для бонсай в малой дозе по инструкции; зимой при слабом росте сократите подкормку.","growthRate":"В тепле постепенно выпускает мелкие листья и побеги; скорость роста зависит от света и объёма плошки. Форму поддерживают обрезкой."}'::jsonb),
 (82,'Бонсай Самшит Харланда','{"humidity":"Самшиту Харланда достаточно обычной влажности воздуха, если корни в маленькой плошке не пересыхают. Зимой держите вдали от горячей батареи.","temperature":"Самшит Харланда не морозостоек как обычный садовый самшит. Летом держите в защищённом месте на улице, а зимой — в светлом прохладном помещении около 10 °C без мороза.","soil":"Подойдёт структурный, дренируемый субстрат для уличного бонсай с отверстиями в плошке. Длительного застоя воды быть не должно.","repotting":"Проверяйте корни ранней весной; при тесном коме пересадите, обновив часть субстрата и аккуратно подрезав корни.","fertilizer":"В период весенне-летнего роста подкармливайте умеренно сбалансированным удобрением для бонсай по инструкции; зимой подкормка не нужна.","growthRate":"Растёт постепенно и сохраняет листву круглый год; весной появляются новые мелкие побеги, которым придают форму стрижкой."}'::jsonb),
 (83,'Бонсай Сосна','{"temperature":"Сосновый бонсай выращивают на открытом воздухе с естественной сменой сезонов; постоянное содержание в тёплой комнате ему не подходит. Зимой защищайте плошку от пересыхания и сильного промерзания корней.","repotting":"Уличный бонсай пересаживают с работой с корнями весной; в мягком климате возможна осенняя пересадка. Точный режим зависит от вида сосны.","fertilizer":"Подкормки уличного бонсай проводят преимущественно с весны до осени, когда дерево активно растёт; зимой их прекращают."}'::jsonb),
 (86,'Бонсай яблоня домашняя','{"humidity":"Яблоня — уличный бонсай и не нуждается в комнатной влажности. Неглубокую плошку регулярно проверяйте, особенно во время цветения и развития плодов.","temperature":"Яблоне необходим зимний покой на холоде; тёплая квартира зимой ей не подходит. Корни в плошке защищайте от экстремального промерзания.","soil":"Используйте плодородный, но дренируемый субстрат для уличного бонсай. Дренажные отверстия позволяют избежать застоя воды.","repotting":"Пересаживайте в конце покоя до сильного весеннего роста, если корням тесно, осторожно обновляя субстрат и подрезая корни.","fertilizer":"В сезон роста давайте умеренную подкормку для плодовых контейнерных растений или бонсай по инструкции; зимой не подкармливайте.","growthRate":"Весной распускает листья и может цвести, летом растут побеги и плоды, осенью листья опадают. Плодоношение зависит от сорта и опыления."}'::jsonb),
 (87,'Венерина мухоловка','{"humidity":"Венерина мухоловка любит влажный воздух, но нуждается и в движении воздуха. Не накрывайте её герметично без вентиляции.","temperature":"Растению нужен сезонный покой: зимой обеспечьте прохладу, а не круглогодичную жару комнаты. Во время роста держите на очень светлом месте.","soil":"Используйте бедный питательными веществами субстрат для хищных растений без обычного удобрения. Вода — дождевая или другая с низким содержанием солей.","repotting":"Пересаживайте в конце зимнего покоя или ранней весной в подходящий субстрат для хищных растений, когда горшок тесен или смесь изношена.","fertilizer":"Не подкармливайте почву удобрением: корни приспособлены к бедному субстрату. Насекомых растение ловит самостоятельно.","growthRate":"Ловушки и листья активно появляются весной и летом; на зимнем покое надземная часть может уменьшиться, что не означает гибель растения."}'::jsonb),
 (89,'Даваллия','{"humidity":"Комнатной даваллии полезна повышенная влажность воздуха; избегайте соседства с горячей батареей и пересушивания корневища.","soil":"Используйте рыхлый воздухопроницаемый субстрат для эпифитных папоротников с корой и крупными органическими компонентами.","repotting":"При пересадке не закапывайте ползучее чешуйчатое корневище глубоко в грунт; деление проводят весной.","temperature":"Берегите комнатный папоротник от мороза и холодных сквозняков; конкретный минимум зависит от неуказанного вида."}'::jsonb),
 (91,'Дипсис Арека','{"humidity":"Этой пальме полезна повышенная влажность воздуха. Держите вдали от отопительных приборов и используйте поддон с влажным керамзитом без контакта дна с водой.","temperature":"Дипсис теплолюбив: держите в комнате без холодных сквозняков; зимой желательно не опускать температуру ниже примерно 13 °C.","soil":"Нужен рыхлый, дренируемый субстрат для комнатных пальм. Горшок должен иметь отверстия и не оставаться в стоячей воде.","repotting":"Пересаживайте весной, когда корни освоят горшок, в ёмкость лишь немного шире. Корни пальм тревожьте как можно меньше.","fertilizer":"Во время роста давайте сбалансированное жидкое удобрение для пальм два-три раза за сезон по инструкции; зимой подкармливайте меньше.","growthRate":"Новые перистые листья появляются постепенно; в комнатном горшке пальма растёт медленнее, чем в природе. Старые нижние листья со временем усыхают."}'::jsonb),
 (92,'Дипсис Арека','{"humidity":"Этой пальме полезна повышенная влажность воздуха. Держите вдали от отопительных приборов и используйте поддон с влажным керамзитом без контакта дна с водой.","temperature":"Дипсис теплолюбив: держите в комнате без холодных сквозняков; зимой желательно не опускать температуру ниже примерно 13 °C.","soil":"Нужен рыхлый, дренируемый субстрат для комнатных пальм. Горшок должен иметь отверстия и не оставаться в стоячей воде.","repotting":"Пересаживайте весной, когда корни освоят горшок, в ёмкость лишь немного шире. Корни пальм тревожьте как можно меньше.","fertilizer":"Во время роста давайте сбалансированное жидкое удобрение для пальм два-три раза за сезон по инструкции; зимой подкармливайте меньше.","growthRate":"Новые перистые листья появляются постепенно; в комнатном горшке пальма растёт медленнее, чем в природе. Старые нижние листья со временем усыхают."}'::jsonb),
 (104,'Драцена Сандера','{"humidity":"При обычной комнатной влажности драцена Сандера растёт нормально. Держите вдали от горячей батареи и не оставляйте корни в застоявшейся воде.","temperature":"Держите в тёплой комнате без холодных сквозняков и резких перепадов температуры.","soil":"Для выращивания в горшке подойдёт рыхлый дренируемый субстрат для комнатных растений. Если стебли стоят в воде, регулярно меняйте её и промывайте ёмкость.","repotting":"Растения в грунте пересаживайте весной, когда корни заполнят горшок. Стебли, выращиваемые в воде, переносят в грунт аккуратно, не заглубляя их чрезмерно.","fertilizer":"В грунте подкармливайте во время роста слабым раствором удобрения для комнатных растений по инструкции; при выращивании в воде используйте только подходящие малые дозы.","growthRate":"Удлинение стеблей и появление новых листьев обычно умеренное; при недостатке света рост замедляется."}'::jsonb),
 (116,'Каладиум','{"humidity":"Каладиум предпочитает более влажный воздух во время роста листьев; держите его вдали от горячей батареи.","temperature":"Теплолюбивое клубневое растение: не допускайте холода; после естественного отмирания листьев клубень храните сухо и без мороза.","soil":"Используйте плодородный рыхлый субстрат с хорошим дренажом и слегка кислой реакцией; летом грунт должен оставаться умеренно влажным.","repotting":"После периода покоя высаживайте клубень в свежий субстрат в тёплое время года; не заглубляйте его слишком сильно.","fertilizer":"Во время активного роста листьев подкармливайте регулярно по инструкции; после начала периода покоя подкормку прекращайте.","growthRate":"Весной и летом быстро выпускает листья из клубня; зимой листва естественно отмирает, и растение переходит в покой."}'::jsonb),
 (120,'Калла','{"soil":"Во время роста калле нужен влагоёмкий, но дренируемый универсальный грунт; пересушивать его полностью не следует.","temperature":"У разных видов зимостойкость различается, поэтому горшечный экземпляр неизвестного вида защищайте от заморозков.","repotting":"Пересаживайте весной при возобновлении роста и тесноте горшка. Новый горшок берите немного просторнее, сохраняя рыхлый дренируемый грунт."}'::jsonb),
 (121,'Клузия','{"soil":"Для выращиваемых в комнате клузий используйте рыхлый, хорошо дренируемый грунт с добавлением крупного песка или другого разрыхлителя.","repotting":"Пересаживайте по мере заполнения горшка корнями, избегая частого беспокойства корневого кома. Новый горшок берите лишь немного больше прежнего.","temperature":"Это тропический род: комнатный экземпляр защищайте от заморозков и холодных сквозняков; точный температурный режим уточняют по виду."}'::jsonb),
 (123,'Кофе Арабика','{"humidity":"Кофейному дереву нужна умеренная или повышенная влажность воздуха; держите вдали от батареи и холодных сквозняков.","temperature":"Выращивайте в тёплой светлой комнате, защищая от холодных потоков воздуха и резких перепадов температуры.","soil":"Подойдёт рыхлый субстрат на основе суглинка с органическим компонентом и хорошим дренажом, как рекомендует RHS для кофе в контейнере.","repotting":"Пересаживайте весной примерно раз в 2–3 года или при тесном горшке, выбирая ёмкость немного шире прежней.","fertilizer":"В период активного роста вносите сбалансированное жидкое удобрение по инструкции примерно раз в две недели; зимой сократите подкормку.","growthRate":"Листья и побеги нарастают в тёплый светлый сезон; цветение и плоды возможны лишь у достаточно зрелого растения в подходящих условиях."}'::jsonb),
 (124,'Крассула','{"humidity":"Как суккулент, крассула обычно не требует повышенной влажности воздуха; избегайте постоянной сырости вокруг листьев.","soil":"Посадите в рыхлый грунт для суккулентов с крупными минеральными разрыхлителями и обязательным оттоком лишней воды.","repotting":"Пересаживайте весной, когда растение перерастёт горшок; не берите ёмкость значительно больше корневого кома.","fertilizer":"Во время активного роста допустима умеренная подкормка удобрением для суккулентов примерно раз в месяц; зимой без роста не подкармливайте."}'::jsonb),
 (125,'Крестовник Роули (Сенецио)','{"humidity":"Крестовник Роули предпочитает сухой воздух; опрыскивать мясистые листья не нужно.","temperature":"Держите в тёплом светлом месте; зимой прохладнее и суше, но без морозов. У RHS указан зимний диапазон около 13–16 °C.","soil":"Нужен очень рыхлый, быстро просыхающий субстрат для кактусов и суккулентов. Горшок обязательно с дренажными отверстиями.","repotting":"Пересаживайте весной, если корням тесно, в небольшую ёмкость с новым дренируемым субстратом. Хрупкие свисающие побеги берегите от перелома.","fertilizer":"Весной и летом при росте изредка используйте удобрение для суккулентов в небольшой дозе по инструкции; зимой не подкармливайте.","growthRate":"Тонкие побеги с шаровидными листьями постепенно удлиняются и свисают; зимой рост замедляется."}'::jsonb),
 (126,'Кротон (Кодиеум)','{"humidity":"Требует повышенной влажности воздуха; при сухости листья могут терять вид. Поможет увлажнитель или поддон с влажным керамзитом.","temperature":"Держите при постоянном тепле около 18–35 °C, не ниже 15 °C; холодный сквозняк может вызвать листопад.","soil":"Нужен рыхлый, быстро дренируемый кислый субстрат; RHS рекомендует три части кислого грунта и одну часть гравия.","repotting":"После 1–2 лет в исходном горшке пересаживайте весной, когда корням тесно; новый горшок берите лишь немного больше.","fertilizer":"Во время активного роста подкармливайте удобрением для комнатных растений по инструкции; зимой при замедлении роста сократите.","growthRate":"В тёплый светлый сезон выпускает новые яркие листья; зимой при недостатке света рост замедляется."}'::jsonb),
 (130,'Лавр благородный','{"humidity":"Лавру достаточно обычной влажности воздуха. На ветру и в жару небольшой контейнер пересыхает быстрее, поэтому проверяйте субстрат.","temperature":"Лавр выращивайте на солнечном или слегка притенённом месте; контейнерное растение зимой защищайте от сильного мороза. Круглогодичная жаркая комната не идеальна.","soil":"Используйте хорошо дренируемый субстрат для контейнерных древесных растений. Не допускайте долгого застоя воды у корней.","repotting":"Пересаживайте контейнерный лавр весной примерно раз в 2–3 года или когда корни заполнят горшок; новый горшок берите немного больше.","fertilizer":"Во время активного роста подкармливайте контейнерное растение сбалансированным удобрением по инструкции; зимой при слабом росте не подкармливайте.","growthRate":"Вечнозелёный лавр растёт постепенно, давая новые побеги в тёплый сезон. Формирующая стрижка помогает сохранять крону."}'::jsonb),
 (131,'Лавр куст','{"humidity":"Лавру достаточно обычной влажности воздуха. На ветру и в жару небольшой контейнер пересыхает быстрее, поэтому проверяйте субстрат.","temperature":"Лавр выращивайте на солнечном или слегка притенённом месте; контейнерное растение зимой защищайте от сильного мороза. Круглогодичная жаркая комната не идеальна.","soil":"Используйте хорошо дренируемый субстрат для контейнерных древесных растений. Не допускайте долгого застоя воды у корней.","repotting":"Пересаживайте контейнерный лавр весной примерно раз в 2–3 года или когда корни заполнят горшок; новый горшок берите немного больше.","fertilizer":"Во время активного роста подкармливайте контейнерное растение сбалансированным удобрением по инструкции; зимой при слабом росте не подкармливайте.","growthRate":"Вечнозелёный лавр растёт постепенно, давая новые побеги в тёплый сезон. Формирующая стрижка помогает сохранять крону."}'::jsonb),
 (134,'Ливистона','{"humidity":"При сухом воздухе отопления повышайте влажность рядом с пальмой и очищайте листья от пыли; горшок не должен стоять в воде.","soil":"Для комнатной пальмы подходит качественный грунт для комнатных растений с дренажом; можно добавить крупный песок.","repotting":"Пальму переваливают ранней весной, если корням тесно; крупным экземплярам вместо частой пересадки обновляют верхний слой грунта.","fertilizer":"После пересадки подождите 6–8 недель; затем в период роста применяйте жидкое универсальное удобрение по инструкции."}'::jsonb),
 (139,'Маранта','{"humidity":"Поддерживайте высокую влажность воздуха; поможет увлажнитель или поддон с влажным керамзитом.","temperature":"Содержите в тёплой комнате без холодного сквозняка; берегите листья от прямого потока батареи.","soil":"Нужен влагоёмкий, но хорошо дренируемый субстрат для комнатных растений; грунт не должен заболачиваться.","repotting":"Пересаживайте весной при тесном горшке; при пересадке разросшееся корневище можно аккуратно разделить.","fertilizer":"RHS рекомендует подкармливать маранту примерно раз в месяц в период активного роста, зимой уменьшить.","growthRate":"В тёплый сезон даёт новые листья и постепенно расползающиеся побеги; зимой рост замедляется."}'::jsonb),
 (140,'Микросорум Крокодилус','{"humidity":"Нужна повышенная влажность воздуха: поставьте рядом поддон с влажной галькой, но не оставляйте горшок стоять в воде.","temperature":"Держите в тепле без холодных сквозняков; этот нежный папоротник не следует оставлять на холодном подоконнике зимой.","soil":"Нужен рыхлый, хорошо дренируемый субстрат для эпифитных папоротников: с корой, листовым перегноем и крупными разрыхлителями.","repotting":"Пересаживайте весной, когда корням станет тесно; возьмите лишь немного больший горшок и сохраните воздушную структуру субстрата.","fertilizer":"В период активного роста подкармливайте слабым раствором удобрения для декоративно-лиственных растений; зимой без роста подкормку сократите.","growthRate":"Растёт постепенно, образуя куртину; по данным RHS, до зрелого размера растение дорастает примерно за 2–5 лет."}'::jsonb),
 (142,'Мимоза стыдливая','{"humidity":"Мимозе стыдливой полезна умеренно влажная атмосфера; избегайте горячего сухого воздуха от батареи и резких перемен условий.","temperature":"Держите в тёплой светлой комнате без холодных сквозняков. Растение чувствительно к заморозкам.","soil":"Используйте рыхлый, питательный, хорошо дренируемый субстрат для комнатных растений и горшок с отверстиями.","repotting":"Пересаживайте весной, если корням тесно, аккуратно сохраняя корневой ком и выбирая горшок лишь немного шире.","fertilizer":"Во время роста подкармливайте сбалансированным жидким удобрением в небольшой дозе по инструкции; при слабом росте зимой сокращайте.","growthRate":"Это быстрорастущее травянистое растение; листья складываются при прикосновении. С возрастом декоративность может снижаться."}'::jsonb),
 (143,'Мирсина африканская','{"humidity":"Мирсина переносит обычную влажность воздуха. Для контейнера важнее не пересушивать корневой ком и не держать его в стоячей воде.","temperature":"Держите растение на свету, но в холодном климате защищайте контейнер от сильного мороза. Тёплая тёмная комната зимой нежелательна.","soil":"Используйте плодородный, но хорошо дренируемый субстрат. Корни не должны долго находиться в плотной мокрой земле.","repotting":"Пересаживайте весной, когда корни заполнят горшок, в чуть более просторную ёмкость; штамбовую форму закрепляйте устойчиво.","fertilizer":"С весны до конца лета применяйте сбалансированное удобрение для контейнерных кустарников по инструкции; зимой подкормку прекратите.","growthRate":"Растёт медленно, сохраняя мелкую вечнозелёную листву; новые побеги появляются главным образом в тёплый сезон."}'::jsonb),
 (144,'Мирсина на штамбе','{"humidity":"Мирсина переносит обычную влажность воздуха. Для контейнера важнее не пересушивать корневой ком и не держать его в стоячей воде.","temperature":"Держите растение на свету, но в холодном климате защищайте контейнер от сильного мороза. Тёплая тёмная комната зимой нежелательна.","soil":"Используйте плодородный, но хорошо дренируемый субстрат. Корни не должны долго находиться в плотной мокрой земле.","repotting":"Пересаживайте весной, когда корни заполнят горшок, в чуть более просторную ёмкость; штамбовую форму закрепляйте устойчиво.","fertilizer":"С весны до конца лета применяйте сбалансированное удобрение для контейнерных кустарников по инструкции; зимой подкормку прекратите.","growthRate":"Растёт медленно, сохраняя мелкую вечнозелёную листву; новые побеги появляются главным образом в тёплый сезон."}'::jsonb),
 (145,'Мирт','{"humidity":"Мирту достаточно обычной влажности воздуха, но горячий сухой воздух батареи нежелателен. Проверяйте влажность небольшого горшка в жару.","temperature":"Мирт любит свет и сезонность: зимой желательно светлое прохладное защищённое от мороза место. В жаркой тёмной комнате листья могут осыпаться.","soil":"Подойдёт рыхлый, плодородный и дренируемый субстрат для контейнерных кустарников. Обязательны отверстия для стока воды.","repotting":"Весной при тесном корневом коме пересадите в горшок немного шире, не заглубляя основание ствола. Крупным экземплярам можно менять верхний слой земли.","fertilizer":"В период активного роста подкармливайте сбалансированным удобрением для контейнерных растений по инструкции; зимой подкормку сократите.","growthRate":"Мирт медленно или умеренно наращивает мелкие листья и древеснеющие побеги; крону можно поддерживать лёгкой обрезкой."}'::jsonb),
 (146,'Мирт на штамбе','{"humidity":"Мирту достаточно обычной влажности воздуха, но горячий сухой воздух батареи нежелателен. Проверяйте влажность небольшого горшка в жару.","temperature":"Мирт любит свет и сезонность: зимой желательно светлое прохладное защищённое от мороза место. В жаркой тёмной комнате листья могут осыпаться.","soil":"Подойдёт рыхлый, плодородный и дренируемый субстрат для контейнерных кустарников. Обязательны отверстия для стока воды.","repotting":"Весной при тесном корневом коме пересадите в горшок немного шире, не заглубляя основание ствола. Крупным экземплярам можно менять верхний слой земли.","fertilizer":"В период активного роста подкармливайте сбалансированным удобрением для контейнерных растений по инструкции; зимой подкормку сократите.","growthRate":"Мирт медленно или умеренно наращивает мелкие листья и древеснеющие побеги; крону можно поддерживать лёгкой обрезкой."}'::jsonb),
 (147,'Мирт спиральный','{"humidity":"Мирту достаточно обычной влажности воздуха, но горячий сухой воздух батареи нежелателен. Проверяйте влажность небольшого горшка в жару.","temperature":"Мирт любит свет и сезонность: зимой желательно светлое прохладное защищённое от мороза место. В жаркой тёмной комнате листья могут осыпаться.","soil":"Подойдёт рыхлый, плодородный и дренируемый субстрат для контейнерных кустарников. Обязательны отверстия для стока воды.","repotting":"Весной при тесном корневом коме пересадите в горшок немного шире, не заглубляя основание ствола. Крупным экземплярам можно менять верхний слой земли.","fertilizer":"В период активного роста подкармливайте сбалансированным удобрением для контейнерных растений по инструкции; зимой подкормку сократите.","growthRate":"Мирт медленно или умеренно наращивает мелкие листья и древеснеющие побеги; крону можно поддерживать лёгкой обрезкой."}'::jsonb),
 (153,'Муса (Банан)','{"humidity":"Крупным листьям банана полезен влажный воздух, особенно в жару; обеспечьте также движение воздуха без холодного сквозняка.","temperature":"Большинство Musa не переносит мороз; до осеннего похолодания заносите растение в защищённое место. Точная зимовка зависит от вида.","soil":"Нужен питательный, влагоёмкий, но хорошо дренируемый грунт и вместительный устойчивый горшок.","repotting":"Контейнерный банан пересаживайте весной; крупные растения обычно раз в 2–3 года в горшок шире прежнего на 10–15 см.","fertilizer":"Во время активного роста подкармливайте регулярно удобрением для контейнерных растений по инструкции; зимой сократите.","growthRate":"В тепле и при хорошем питании растёт быстро, выпуская крупные листья; размер зависит от вида и сорта."}'::jsonb),
 (154,'Непентес','{"humidity":"Непентесу нужен тёплый и влажный воздух, чтобы развивать кувшинчики; полезен увлажнитель и свободный доступ воздуха.","temperature":"Это тропическое растение: держите в тепле и без холодных сквозняков. Точный режим зависит от вида и требует проверки этикетки.","soil":"Не используйте обычный питательный грунт: нужен бедный, рыхлый субстрат для хищных растений с хорошим дренажом.","repotting":"Пересаживайте только при разрушении субстрата или тесноте корней, используя специализированную смесь для непентеса.","fertilizer":"Обычное удобрение для комнатных растений не применяйте: избыток минеральных солей вреден хищному растению.","growthRate":"Новые листья и кувшинчики развиваются в тепле и при достаточной влажности; в сухом воздухе кувшинчики могут не образовываться."}'::jsonb),
 (165,'Пахира Акватика плетеная','{"humidity":"Пахире полезен умеренно влажный воздух, но она не должна стоять рядом с горячей батареей. Плетёные стволы должны оставаться сухими у основания.","temperature":"Содержите в тёплой комнате без холодных сквозняков и резких перепадов температуры.","soil":"Используйте открытый, рыхлый, хорошо дренируемый субстрат для комнатных растений. Излишняя вода должна свободно вытекать из горшка.","repotting":"Пересаживайте весной, когда корни заполнят горшок, в ёмкость лишь немного шире; не заглубляйте сплетённые стволы.","fertilizer":"Во время активного роста подкармливайте сбалансированным удобрением для комнатных растений по инструкции; зимой при слабом росте уменьшайте частоту.","growthRate":"В тёплой светлой комнате выпускает новые пальчатые листья и постепенно древеснеет; в горшке растёт медленнее, чем в природе."}'::jsonb),
 (167,'Платицериум','{"humidity":"Платицериуму как эпифитному папоротнику нужен влажный воздух и хорошая вентиляция; сухая батарея ему не подходит.","temperature":"Держите в тепле, ориентир для эпифитных папоротников — выше 16 °C; избегайте холодного сквозняка.","soil":"Не сажайте в плотную землю: используйте рыхлый воздухопроницаемый субстрат для эпифитных папоротников либо закрепите на опоре.","repotting":"Пересаживайте или перемонтируйте весной, только когда корни и розетка переросли ёмкость; не удаляйте живые щитковые листья.","fertilizer":"Весной и летом давайте слабое удобрение для орхидей или папоротников по инструкции; не перекармливайте.","growthRate":"Новые вайи появляются постепенно в тёплый сезон; щитковые листья со временем буреют, оставаясь частью растения."}'::jsonb),
 (168,'Пуансеттия (рождественская звезда)','{"humidity":"Держите вдали от горячей батареи и очень сухого воздуха; умеренная влажность помогает сохранить прицветники.","temperature":"Берегите от холода, сквозняков и резких перепадов при перевозке; держите в тёплой светлой комнате.","soil":"Если сохраняете пуансеттию после праздников, пересадите в смесь трёх частей питательного суглинистого грунта и одной части гравия; нужен сток воды.","repotting":"Если сохраняете растение после праздничного сезона, пересаживайте весной, когда начнётся новый рост, в горшок немного больше.","fertilizer":"Если сохраняете растение на следующий год, подкармливайте раз в месяц удобрением с повышенным калием по инструкции.","growthRate":"После зимнего цветного периода рост замедляется; весной при хорошем свете появляются новые зелёные листья и побеги."}'::jsonb),
 (170,'Рипсалис','{"humidity":"Рипсалис — лесной эпифитный кактус, ему полезен более влажный воздух; это исключение из правил для пустынных кактусов.","temperature":"Держите в тёплом помещении без мороза и холодного сквозняка; точный нижний предел зависит от вида.","soil":"Нужен рыхлый, быстро дренируемый субстрат для эпифитных кактусов в горшке с отверстиями.","repotting":"Пересаживайте весной лишь когда корни освоят горшок или субстрат уплотнился; новую ёмкость берите ненамного больше.","fertilizer":"Во время роста можно подкармливать раз в месяц слабым удобрением с невысоким содержанием азота; зимой сократите.","growthRate":"В светлый сезон постепенно наращивает свисающие разветвлённые побеги; зимой рост обычно слабее."}'::jsonb),
 (180,'Синнингия Глоксиния Соната','{"humidity":"Синнингии полезна умеренная влажность воздуха. Не опрыскивайте опушённые листья и цветки: капли могут оставлять повреждения.","temperature":"Держите в тёплой комнате во время роста и цветения; после отмирания листьев клубень проходит период покоя в более прохладном сухом месте.","soil":"Подойдёт лёгкий, воздухопроницаемый субстрат для цветущих комнатных растений с хорошим дренажом; клубень нельзя держать в сырой плотной земле.","repotting":"Пересаживайте клубень весной после покоя, когда появится новый рост, в свежий рыхлый субстрат. Не заглубляйте его слишком сильно.","fertilizer":"В период роста и цветения давайте удобрение для цветущих растений в умеренной дозе по инструкции; после окончания роста подкормку прекращайте.","growthRate":"После весеннего отрастания быстро образует листья и цветки; затем надземная часть может отмереть на сезонный покой клубня."}'::jsonb),
 (188,'Тилландсия','{"humidity":"Воздушные тилландсии поглощают влагу листьями; им нужен доступ воздуха и регулярное увлажнение, после которого растение должно полностью просыхать.","temperature":"Держите при температуре выше 12 °C; летом допустима жара до 30 °C при достаточной влажности и хорошей вентиляции.","soil":"Обычный грунт не нужен: закрепите растение на ветке, коре или камне, обеспечив свободный доступ воздуха к листьям.","repotting":"Пересадка в грунт не требуется. При необходимости снимите тилландсию с опоры и закрепите на новой, не закрывая основание розетки.","fertilizer":"Летом изредка добавляйте в воду для замачивания слабое удобрение для орхидей; затем дайте растению полностью просохнуть.","growthRate":"Растёт постепенно; после цветения материнская розетка обычно образует дочерние побеги и со временем отмирает."}'::jsonb),
 (189,'Тилландсия микс','{"humidity":"Воздушные тилландсии поглощают влагу листьями; им нужен доступ воздуха и регулярное увлажнение, после которого растение должно полностью просыхать.","temperature":"Держите при температуре выше 12 °C; летом допустима жара до 30 °C при достаточной влажности и хорошей вентиляции.","soil":"Обычный грунт не нужен: закрепите растение на ветке, коре или камне, обеспечив свободный доступ воздуха к листьям.","repotting":"Пересадка в грунт не требуется. При необходимости снимите тилландсию с опоры и закрепите на новой, не закрывая основание розетки.","fertilizer":"Летом изредка добавляйте в воду для замачивания слабое удобрение для орхидей; затем дайте растению полностью просохнуть.","growthRate":"Растёт постепенно; после цветения материнская розетка обычно образует дочерние побеги и со временем отмирает."}'::jsonb),
 (191,'Туя Брабант','{"humidity":"Это уличная туя; комнатное увлажнение ей не требуется. В горшке следите, чтобы ком не пересыхал при ветре и жаре.","temperature":"Выращивайте на улице круглый год. Если туя посажена в контейнер, зимой защитите горшок и корни от экстремального промерзания; тёплая квартира не подходит.","soil":"Нужен плодородный, хорошо дренируемый субстрат или грунт. Застой воды у корней недопустим.","repotting":"Контейнерную тую пересаживайте весной, когда корни заполнят горшок, увеличивая объём постепенно. При посадке в грунт не заглубляйте корневую шейку.","fertilizer":"Весной при необходимости внесите удобрение для хвойных по инструкции; поздние азотные подкормки нежелательны перед зимой.","growthRate":"Сорт «Брабант» растёт быстро и образует плотную вечнозелёную крону. Основной прирост приходится на весну и лето."}'::jsonb),
 (192,'Фиалка в ассортименте','{"humidity":"Любит влажный воздух: поставьте горшок над влажным гравием так, чтобы дно не касалось воды. Бархатистые листья не опрыскивайте.","temperature":"Поддерживайте примерно 18–24 °C днём и около 16 °C ночью; защищайте от холодных сквозняков и резких перепадов.","soil":"Нужен лёгкий воздухопроницаемый грунт для сенполий или комнатных растений; избегайте плотного и постоянно мокрого субстрата.","repotting":"Пересаживайте весной примерно раз в 2–3 года в неглубокий горшок лишь немного больше корневого кома.","fertilizer":"Весной и летом для цветения вносите разбавленное жидкое удобрение для комнатных растений раз в 3–4 недели по инструкции.","growthRate":"Компактная розетка может цвести многие месяцы при достаточном рассеянном свете; низкая влажность и слабый свет замедляют рост и цветение."}'::jsonb),
 (208,'Фикус Микрокарпа Гинсенг','{"humidity":"Фикусу полезна умеренная влажность воздуха; в очень сухой комнате можно увлажнять воздух рядом с растением.","temperature":"Держите в тёплом помещении без холодного сквозняка и резких перемен места; это тропический фикус.","soil":"Нужен рыхлый, дренируемый субстрат для комнатных растений и горшок с отверстиями для стока лишней воды.","repotting":"Проверяйте тесноту корней весной; пересаживайте в горшок лишь немного больше, сохраняя форму утолщённого основания.","fertilizer":"Весной и летом подкармливайте удобрением для комнатных растений по инструкции; в короткий зимний день сократите.","growthRate":"Листья и побеги активнее нарастают в светлый сезон; форму кроны можно поддерживать обрезкой молодых побегов."}'::jsonb),
 (228,'Фиттония','{"humidity":"Нуждается в высокой влажности воздуха; лучше всего чувствует себя в террариуме или у увлажнителя.","temperature":"Держите в тепле, не ниже 15 °C, вдали от холодного стекла и сквозняка.","soil":"Нужен влагоёмкий, но дренируемый грунт для комнатных растений; нельзя оставлять корни в стоячей воде.","repotting":"Весной пересаживайте, когда корни освоят ёмкость; низкий разросшийся куст можно аккуратно разделить.","fertilizer":"Фиттонии достаточно половинной дозы удобрения для комнатных растений раз в 2–3 месяца; частые подкормки ей не нужны.","growthRate":"Низкое растение медленно разрастается в стороны; в тёплый светлый сезон выпускает новые узорчатые листья."}'::jsonb),
 (229,'Хамедорея Элеганс','{"humidity":"Обычная влажность комнаты допустима, но при сухом воздухе кончики листьев могут буреть; поможет поддон с влажным керамзитом.","temperature":"Лучше растёт при 20–27 °C весной и летом; зимой переносит более прохладный режим, но не ниже примерно 10 °C.","soil":"Подойдёт лёгкий, быстро дренируемый слабокислый грунт; RHS предлагает три части кислого субстрата и одну часть перлита.","repotting":"Растёт медленно и годами может оставаться в исходном горшке. Пересаживайте весной лишь при плотных корнях, в ёмкость на пару сантиметров шире.","fertilizer":"При слабом росте можно подкармливать сбалансированным жидким удобрением раз в месяц с весны до осени.","growthRate":"Одна из медленно растущих комнатных пальм; новые перистые листья появляются постепенно, особенно весной и летом."}'::jsonb),
 (238,'Цикас (саговник)','{"humidity":"Цикас переносит обычную влажность воздуха. Пыль с жёстких листьев можно удалять мягкой влажной тканью; не держите растение у горячей батареи.","temperature":"Растение не морозостойко в контейнере: зимой держите в светлом прохладном месте без замерзания, летом можно вынести на защищённое место постепенно.","soil":"Нужен очень хороший дренаж и рыхлый субстрат для кадочных растений. Сырая плотная земля опасна для корней и основания ствола.","repotting":"Пересаживайте редко, только когда корни заполнят горшок, весной в ёмкость немного шире. Не заглубляйте верхушку каудекса.","fertilizer":"В период появления новых листьев используйте сбалансированное удобрение для кадочных растений по инструкции; зимой подкормка не нужна.","growthRate":"Цикас растёт очень медленно: новые листья могут появляться сразу группой, а затем долго сохраняться без заметного прироста."}'::jsonb),
 (240,'Циртомиум','{"soil":"Папоротнику нужен влагоёмкий, но дренируемый грунт с органическим веществом; не допускайте застоя воды у корней.","repotting":"Пересаживайте при заполнении горшка корнями, удобнее весной; новый горшок берите лишь немного просторнее.","growthRate":"Новые вайи появляются из корневища в сезон роста; скорость и зимнее поведение зависят от вида циртомиума."}'::jsonb),
 (241,'Шеффлера','{"soil":"Для комнатной шеффлеры подходит стандартный грунт для комнатных растений с дренажем и без длительного застоя воды.","fertilizer":"В период роста допустима сбалансированная жидкая подкормка примерно раз в месяц; зимой при слабом росте сократите её."}'::jsonb),
 (242,'Шеффлера (Герда)','{"soil":"Для комнатной шеффлеры подходит стандартный грунт для комнатных растений с дренажем и без длительного застоя воды.","fertilizer":"В период роста допустима сбалансированная жидкая подкормка примерно раз в месяц; зимой при слабом росте сократите её."}'::jsonb),
 (243,'Шеффлера Луизиана','{"soil":"Для комнатной шеффлеры подходит стандартный грунт для комнатных растений с дренажем и без длительного застоя воды.","fertilizer":"В период роста допустима сбалансированная жидкая подкормка примерно раз в месяц; зимой при слабом росте сократите её."}'::jsonb),
 (857,'Замиокулькус Roundleaf D22','{"humidity":"Замиокулькас переносит обычный суховатый воздух квартиры. Опрыскивание не нужно; влажность почвы важнее воздушной.","temperature":"Содержите в тёплой комнате без холодного сквозняка. При низкой температуре полив особенно сокращайте.","soil":"Используйте рыхлый хорошо дренируемый субстрат для комнатных растений с добавкой разрыхлителя. Горшок должен иметь отверстия.","repotting":"Пересаживайте весной, когда корневища и корни заполнят горшок, в ёмкость немного шире прежней. Не берите большой запас сырой земли.","fertilizer":"С апреля по сентябрь подкармливайте умеренно удобрением для комнатных растений, лучше в неполной дозе по инструкции; зимой подкормку сократите.","growthRate":"Растёт медленно: новые побеги появляются нерегулярно, чаще в тёплый светлый сезон. Округлая форма листочков не меняет общий режим ухода вида."}'::jsonb),
 (865,'Кордилина  Киви D10','{"humidity":"Повышенная влажность помогает сохранить листья: RHS рекомендует регулярно опрыскивать растение и периодически очищать листья от пыли.","temperature":"Теплолюбивую кордилину держите в помещении без морозов и холодных сквозняков; летом допустим защищённый вынос на улицу.","soil":"Подойдёт универсальный грунт без торфа с хорошим дренажем; субстрат должен удерживать умеренную влагу без застоя воды.","repotting":"RHS советует ежегодно обновлять верхний слой грунта, а весной переваливать в больший горшок примерно раз в 2–3 года.","fertilizer":"Во время роста подкармливайте сбалансированным жидким удобрением один раз в месяц; зимой подкормки прекратите.","growthRate":"Растёт постепенно как прямостоячий декоративный кустарник; по данным RHS, до зрелого размера дорастает за 2–5 лет."}'::jsonb);
